/*
  Cardio Part 1 Diseases tool: Cardiac Devices lecture (Gulczinski).
  Same shape as data/diseases-endocrine.js; uses window.DiseaseContent helpers.

  Sources: source-material/cardio-part-1/text/cardiac-devices.md (slides + notes)
  and the "Cardiac Device Objectives" block of objectives.txt.
  This lecture teaches devices rather than classic diseases, so each entry is a
  clinical condition or scenario the lecture manages: the bradyarrhythmia that
  may need a pacemaker, the patient living with a permanent pacemaker, the
  patient at risk of sudden cardiac death who needs an ICD, the patient whose
  ICD has fired, device precautions and EMI, the device patient going to
  surgery, lead complications, and device infection.

  Picture-only slides are photos, a device CXR, and diagrams; their teaching
  content is carried by the slide text (same as data/cardiac-devices.js).
  Clarification (objective 7 workup): the slides name persistent bacteremia and
  a lead vegetation on TEE; blood cultures are stated as the way persistent
  bacteremia is shown, matching data/cardiac-devices.js.

  Question ids are "<disease id>|<index>" and progress is saved against them:
  only APPEND questions to a disease; never insert, delete, or reorder.
*/
(function () {
  "use strict";

  var H = window.DiseaseContent;
  var Tbl = H.Tbl, HY = H.HY, Mn = H.Mn, S = H.S, Q = H.Q, D = H.D, L = H.L;

  // ---- Shared reference blocks -------------------------------------------

  var ppmVsIcdTable = Tbl(["", "Permanent pacemaker (PPM)", "ICD"], [
    ["Problem treated", "<strong>Too slow</strong>: disease of the AV node or His-Purkinje system (sometimes the sinus node)", "<strong>Too fast and lethal</strong>: risk of sudden cardiac death from VT/VF"],
    ["Key indications", "Symptomatic sinus node dysfunction (usually HR &lt; 40), symptomatic complete heart block or Mobitz II, asystole &gt; 3 s (≥ 5 s in AF), to facilitate AV node ablation, CRT", "<strong>Secondary</strong>: survivor of VT/VF arrest not due to a completely reversible cause. <strong>Primary</strong>: e.g., <strong>LVEF ≤ 30%</strong> (≥ 40 days post-MI if due to MI)"],
    ["What it delivers", "Pacing impulses", "<strong>80-J shock</strong>, or overdrive pacing; modern TV-ICDs can also pace a bradyarrhythmia"],
    ["Battery", "Typically <strong>~10 years</strong>", "Average <strong>~8 years</strong> (early ICDs: 2 years)"],
    ["Magnet in the OR", "<strong>Asynchronous pacing</strong> at a fixed rate with fixed AV delay", "<strong>Shock function suspended</strong>; external pads on the chest"]
  ]) + HY("Pacemaker = bradycardia. ICD = VT/VF. A magnet makes a pacemaker pace asynchronously and turns an ICD’s shocks off.");

  var codeTable = Tbl(["Position", "Meaning", "Letters"], [
    ["<strong>1st</strong>", "Chamber <strong>paced</strong>", "A = atria, V = ventricle, D = dual"],
    ["<strong>2nd</strong>", "Chamber <strong>sensed</strong>", "A, V, D, O = none"],
    ["<strong>3rd</strong>", "<strong>Response</strong> to a sensed native beat", "I = inhibited; T = triggered (additive depolarization); D = triggered after a sensed atrial event, inhibited after a sensed ventricular event; O = none (paces continuously)"],
    ["<strong>4th</strong>", "<strong>Rate modulation</strong> for chronotropic incompetence", "R = rate-response (“physiologic”) pacing; O = none"],
    ["<strong>5th</strong>", "<strong>Multisite pacing</strong> (CRT)", "A, V, D, O = none"]
  ]) + Mn("Pace – Sense – Respond – Rate – Multisite", "Read the letters left to right: what it Paces, what it Senses, how it Responds, whether it Rate-adapts, and where it Multisite-paces. Usually only the first 3 are documented.");

  var emiTable = Tbl(["Exposure", "Rule"], [
    ["Cell phones, mobile devices, magnets, headphones, wireless chargers", "Keep <strong>&gt; 6 inches (about 15 cm)</strong> from the device site when on"],
    ["Airport security", "ICDs may set off alarms; hand-held metal detector <strong>&lt; 30 seconds</strong> over the site, or request a manual search"],
    ["Welding equipment, high-voltage transformers, motor-generator systems", "Stand <strong>at least 2 feet (0.6 m)</strong> away"],
    ["External defibrillation / pacing pads", "Place <strong>10 cm</strong> from the pulse generator"],
    ["Little or no risk", "Microwaves, TVs and remotes, AM/FM radios, toasters, electric blankets, shavers, drills, computers, scanners, printers, GPS"]
  ]) + Mn("6 inches – 2 feet – 10 cm", "Phone and gadgets: 6 inches. Generators and welders: 2 feet. Defib pads: 10 cm from the generator.");

  window.CARDIO_DISEASES_DEVICES = L("cardiac-devices", "Cardiac Devices", [

    // ------------------------------------------------------------------
    D("dev-bradyarrhythmia", "Bradyarrhythmia Needing a Pacemaker", "Symptomatic slow rhythm from sinus node, AV node, or His-Purkinje disease. Correct reversible causes first; a permanent pacemaker is for symptomatic bradycardia or high-grade block that remains.", [
      S("overview", "Overview", "<p>More than 3 million people in the US have a permanent pacemaker (PPM). Pacemakers are generally placed for <strong>disease of the AV node or the His-Purkinje system</strong>, sometimes for <strong>sinus node disease</strong>.</p>" + ppmVsIcdTable),
      S("presentation", "Presentation", "<ul><li><strong>Exertional dyspnea</strong> and loss of exercise tolerance</li><li><strong>Syncope and near syncope</strong></li><li>The patient or someone around them notices the <strong>heart rate is low</strong></li></ul>"),
      S("reversible", "Reversible causes (correct first)", "<p>Many bradyarrhythmias do <strong>not</strong> warrant a PPM. Before a device is placed, <strong>all reversible causes must be corrected</strong>.</p>" + Tbl(["Reversible cause", "What to do"], [
        ["<strong>AV-nodal blocking medications</strong>", "Hold the offending drug"],
        ["<strong>Severe electrolyte disturbances</strong>, toxic/metabolic abnormalities", "Correct the disturbance"],
        ["<strong>Myocardial ischemia or infarction</strong>", "Treat the underlying disease"],
        ["<strong>Infection</strong>: Lyme disease, infective endocarditis", "Treat the infection"],
        ["<strong>Chest trauma</strong>", "Treat the underlying injury"]
      ]) + "<p>Meanwhile monitor closely; depending on the situation keep a <strong>crash cart nearby</strong> or apply <strong>pacer pads</strong>.</p>" + Mn("Drugs, Lytes, Ischemia, Infection, Trauma", "Rule these out before calling it a pacemaker problem.")),
      S("indications", "Permanent pacemaker indications", "<ul><li><strong>Symptomatic bradycardia from sinus node dysfunction</strong> (sick sinus syndrome), usually HR &lt; 40 bpm</li><li><strong>Symptomatic AV block</strong>, usually <strong>complete heart block</strong> or <strong>second-degree type II</strong></li><li><strong>Asystole &gt; 3 seconds</strong>, or <strong>at least 5 seconds in atrial fibrillation</strong></li><li>To <strong>facilitate AV node ablation</strong></li><li><strong>Cardiac resynchronization therapy</strong> with biventricular pacing</li></ul>" + HY("Symptomatic CHB or Mobitz II with no reversible cause → permanent pacemaker.")),
      S("temporary", "Temporary pacing", "<p>Used only for a short time when there is <strong>life-threatening lack of intrinsic pacing</strong>.</p>" + Tbl(["", "Transcutaneous", "Transvenous"], [
        ["Character", "Temporary and <strong>painful</strong>; often needs <strong>sedation</strong>", "Temporary pacing wires; <strong>not painful</strong>; <strong>strict bedrest</strong>"],
        ["Role", "Minimal time until a transvenous pacer can be placed", "Placed for <strong>&lt; 24 hours</strong> to <strong>bridge to the OR</strong> for a PPM"]
      ]) + "<p><strong>Major indications for temporary pacing:</strong> bradyarrhythmias causing <strong>hemodynamic instability</strong>; <strong>TAVR</strong>; prophylaxis in the post-op period of <strong>valvular surgery</strong>; <strong>Lyme disease</strong> or other infections (<strong>Chagas</strong>) causing interval changes.</p>")
    ], [
      Q("indications", "Which rhythm is a classic indication for a permanent pacemaker when symptomatic?", ["Second-degree AV block type II", "Sinus tachycardia", "First-degree AV block alone", "Premature atrial contractions"], 0, "Symptomatic AV block, usually complete heart block or second-degree type II, is a pacemaker indication."),
      Q("indications", "Sinus node dysfunction usually warrants a pacemaker when it is symptomatic with a heart rate below roughly what value?", ["40 bpm", "60 bpm", "70 bpm", "20 bpm"], 0, "Symptomatic bradycardia from sick sinus syndrome is usually seen with heart rates below 40 bpm."),
      Q("indications", "What pause length is a pacemaker indication in a patient with atrial fibrillation?", ["At least 5 seconds", "At least 1 second", "At least 2 seconds", "At least 10 seconds"], 0, "Asystole longer than 3 seconds, or at least 5 seconds in a patient with atrial fibrillation, is an indication."),
      Q("reversible", "A patient on metoprolol and diltiazem presents with symptomatic bradycardia and stable vitals. What is the first step?", ["Hold the AV-nodal blocking medications and monitor", "Refer for permanent pacemaker", "Place an ICD", "Schedule CRT"], 0, "Bradycardia under the influence of AV-nodal blocking medications is reversible; hold the drugs before considering a device."),
      Q("reversible", "Which is NOT one of the reversible causes of bradyarrhythmia to correct before a pacemaker?", ["Hypertrophic cardiomyopathy", "Severe electrolyte disturbance", "Myocardial ischemia or infarction", "Lyme disease"], 0, "Reversible causes include AV-nodal drugs, electrolyte/toxic-metabolic problems, ischemia/MI, infection (Lyme, IE), and chest trauma."),
      Q("reversible", "A hiker with a tick bite and erythema migrans develops new heart block. What is the appropriate approach?", ["Treat the infection and monitor; temporary pacing if unstable", "Permanent pacemaker immediately", "ICD placement", "No monitoring is needed"], 0, "Lyme disease is a reversible infectious cause; treat the disease. Lyme and Chagas interval changes are indications for temporary, not permanent, pacing."),
      Q("presentation", "Which presentation is typical of a patient who needs a pacemaker?", ["Exertional dyspnea, loss of exercise tolerance, and near syncope", "Palpitations with a rate of 180", "Pleuritic chest pain relieved by leaning forward", "Orthopnea with an S4 and hypertension"], 0, "Patients needing a pacemaker typically present with exertional dyspnea, loss of exercise tolerance, syncope, and near syncope, sometimes with a noted low heart rate."),
      Q("temporary", "Which form of pacing is painful and often requires sedation?", ["Transcutaneous pacing", "Transvenous pacing", "Dual-chamber permanent pacing", "Biventricular pacing"], 0, "Transcutaneous pacing is temporary and painful; it is used for a minimal time until a transvenous pacer can be placed."),
      Q("temporary", "How long are transvenous temporary pacing wires typically left in place?", ["Less than 24 hours", "About 1 week", "About 1 month", "Indefinitely"], 0, "Transvenous wires are placed for under 24 hours to bridge the patient to the OR for a permanent pacemaker; the patient is on strict bedrest."),
      Q("temporary", "Which is a major indication for temporary pacing?", ["Transcatheter aortic valve replacement (TAVR)", "Asymptomatic first-degree AV block", "Primary prophylaxis with LVEF 30%", "Stable sinus bradycardia during sleep"], 0, "Temporary pacing indications: unstable bradyarrhythmias, TAVR, post-op valve surgery prophylaxis, and Lyme/Chagas interval changes."),
      Q("temporary", "A patient with complete heart block is hypotensive and confused. Pads are on and transcutaneous pacing is running. What is the next step?", ["Place a transvenous pacer to bridge to a permanent pacemaker", "Continue transcutaneous pacing for several days", "Place an ICD", "Discharge with outpatient EP follow-up"], 0, "Transcutaneous pacing is only for a minimal time until a transvenous pacer can be placed; transvenous wires bridge to the OR for a PPM.")
    ]),

    // ------------------------------------------------------------------
    D("dev-permanent-pacemaker", "Patient With a Permanent Pacemaker", "Pulse generator in a chest-wall pocket plus leads to the right heart. Know the types (single, dual, biventricular), the 5-letter code, placement, follow-up, and the ~10-year battery.", [
      S("types", "Types & parts", Tbl(["Type", "Leads"], [
        ["<strong>Single chamber</strong>", "One lead to the right ventricle"],
        ["<strong>Dual chamber</strong>", "Two leads: right atrium and right ventricle"],
        ["<strong>Biventricular (CRT)</strong>", "Three leads: RA, RV, and LV. Resynchronizes the heart in <strong>HFrEF</strong> to improve cardiac output"]
      ]) + "<p><strong>Pulse generator</strong> = battery and brain, in a <strong>subcutaneous pocket</strong> in the chest wall. <strong>Leads</strong> carry the impulse to the heart (or only sense). Most are <strong>transvenous</strong> (via the subclavian vein); <strong>epicardial</strong> leads are surgically attached when transvenous placement must be avoided (e.g., <strong>venous stenosis</strong>).</p><p>If a patient needs a pacemaker and an ICD or CRT, combine them so <strong>all run off one pulse generator</strong>.</p>"),
      S("modes", "Pacing modes", Tbl(["Mode", "Behavior", "Risk"], [
        ["<strong>Asynchronous</strong> (fixed-rate)", "Paces at a set rate regardless of intrinsic activity", "Small risk of a <strong>lethal arrhythmia</strong> if the impulse lands on the T-wave’s vulnerable period"],
        ["<strong>Synchronous</strong> (demand)", "Senses for an intrinsic depolarization; paces only if absent", "—"]
      ])),
      S("code", "Pacemaker code", codeTable + "<p><strong>Example – ADI:</strong> paces the right atrium, senses atria and ventricle, and the atrial impulse is inhibited when a native depolarization is sensed. If the atria fail to depolarize on their own, the device is not inhibited and <strong>paces the right atrium</strong>.</p>"),
      S("placement", "Placement & follow-up", "<ul><li>Consult a <strong>cardiac electrophysiologist</strong>; placement can be same-day surgery. If admitted, <strong>NPO at midnight</strong> until EP evaluates; <strong>hold anticoagulant and antiplatelet meds</strong>.</li><li>Placed under <strong>conscious sedation in the cath lab</strong>; local anesthetic to the chest wall; veins accessed directly or by the <strong>Seldinger technique</strong>.</li><li>Wires run to the right heart via the <strong>cephalic, axillary, or subclavian</strong> veins under <strong>fluoroscopy</strong>; a subcutaneous <strong>pocket</strong> is made between skin and pectoralis.</li><li>Most go home the same day or the next.</li></ul>" + Tbl(["When", "Visit"], [
        ["1–2 weeks", "Chest wound check"],
        ["1 month", "Interrogation"],
        ["3 months", "Interrogation"],
        ["Then every 6 months", "Interrogation"]
      ]) + "<p>Pacemakers can be <strong>reprogrammed in the office</strong> while implanted.</p>"),
      S("testing", "Interrogation & battery", "<ul><li><strong>Interrogation</strong> (by the manufacturer’s rep in hospital or the cardiologist in the office) shows the rhythm during events such as <strong>syncope</strong> and how much time is spent in <strong>atrial fibrillation</strong>. It is not used as an event monitor.</li><li><strong>Battery ~10 years</strong> (7–10 years for PPM/ICD depending on use). As it runs down, the pacemaker begins <strong>slowing or changing its pacing mode</strong>.</li><li>Then a <strong>generator change</strong>: replaces the pocket device, <strong>leaves the leads</strong>.</li></ul>" + HY("Battery wearing out → slowing or mode change → generator change (leads stay)."))
    ], [
      Q("types", "How many leads does a dual-chamber pacemaker have, and where?", ["Two: right atrium and right ventricle", "One: right ventricle", "Three: RA, RV, and LV", "Two: right ventricle and left ventricle"], 0, "Dual chamber = two leads, one each to the right atrium and right ventricle."),
      Q("types", "A patient with HFrEF is referred for a device to improve cardiac output by resynchronizing the cardiac cycle. Which device?", ["Biventricular pacemaker (CRT)", "Single-chamber pacemaker", "Subcutaneous ICD", "Transcutaneous pacer"], 0, "A biventricular device has three leads (RA, RV, LV) and provides cardiac resynchronization therapy in HFrEF."),
      Q("types", "When are epicardial pacing leads used instead of transvenous leads?", ["When there is an anatomic reason to avoid transvenous placement, such as venous stenosis", "In every patient over 80", "Only for temporary pacing", "When the patient prefers a smaller scar"], 0, "Epicardial leads are threaded through the chest tissue and surgically attached when transvenous placement must be avoided, such as venous stenosis."),
      Q("modes", "What is the inherent risk of asynchronous (fixed-rate) pacing?", ["A lethal arrhythmia if the impulse falls on the T-wave’s vulnerable period", "Complete loss of pacing", "Pocket hematoma", "Tricuspid stenosis"], 0, "Asynchronous pacing fires regardless of intrinsic activity, with a small risk of R-on-T lethal arrhythmia."),
      Q("code", "In a pacemaker code, what does the second letter describe?", ["The chamber being sensed", "The chamber being paced", "The response to a sensed beat", "Rate modulation"], 0, "1st = paced, 2nd = sensed, 3rd = response, 4th = rate modulation, 5th = multisite pacing."),
      Q("code", "What does an “I” in the third position of a pacemaker code mean?", ["The device is inhibited when it senses the patient’s own beat", "The device is triggered by a native atrial beat", "The device paces continuously", "The device is rate-responsive"], 0, "I = inhibited if the device senses the patient’s native beat."),
      Q("code", "A pacemaker’s code includes an “R” in the fourth position. What does that mean?", ["Rate-response pacing for chronotropic incompetence", "The right ventricle is paced", "The device is reversed in polarity", "The device is inhibited by a native beat"], 0, "The 4th letter is rate modulation; R = rate-response (“physiologic”) pacing."),
      Q("code", "A patient has an ADI pacemaker and their atria fail to depolarize on their own. What will the device do?", ["Pace the right atrium", "Remain inhibited and do nothing", "Pace only the right ventricle", "Deliver a shock"], 0, "ADI paces the atrium; with no sensed native depolarization it is not inhibited, so it paces the right atrium."),
      Q("code", "Which third-letter response means the device is triggered after a sensed atrial event but inhibited after a sensed ventricular event?", ["D", "I", "T", "O"], 0, "D = triggered after a sensed atrial event, inhibited after a sensed ventricular event. O means no response (paces continuously)."),
      Q("placement", "A hospitalized patient is awaiting evaluation for permanent pacemaker placement. Which pre-procedure order is appropriate?", ["NPO at midnight and hold anticoagulant and antiplatelet medications", "Start a heparin drip", "Order an MRI of the chest", "Give a loading dose of amiodarone"], 0, "PPM placement can be same-day surgery: keep the patient NPO at midnight and hold anticoagulants and antiplatelets."),
      Q("placement", "Where and how are permanent pacemakers typically placed?", ["In the cath lab under conscious sedation by an electrophysiologist", "In the OR under general anesthesia by a CT surgeon", "At the bedside without imaging", "In the ED by the emergency physician"], 0, "Pacemakers are typically placed under conscious sedation in the cath lab by the electrophysiologist, using fluoroscopy."),
      Q("placement", "After pacemaker placement, when is the first device interrogation?", ["1 month", "1–2 weeks", "6 months", "1 year"], 0, "Follow-up: 1–2 weeks wound check, interrogation at 1 month and 3 months, then every 6 months."),
      Q("testing", "What is the typical lifespan of a pacemaker battery?", ["About 10 years", "About 2 years", "About 25 years", "About 6 months"], 0, "The battery typically lasts about 10 years (7–10 years depending on use)."),
      Q("testing", "A pacemaker patient’s device begins slowing and changing its pacing mode. What is planned?", ["Generator change, leaving the leads in place", "Extraction of the device and all leads", "Lead replacement only", "Adding an ICD"], 0, "A dwindling battery causes slowing or mode change; the patient gets a generator change that replaces the pocket device but leaves the wires."),
      Q("testing", "A patient with a pacemaker has a syncopal episode. Which test can show the rhythm during the event?", ["Device interrogation", "Chest x-ray", "Echocardiogram", "Lipid panel"], 0, "Pacemakers can be interrogated to determine the rhythm during events such as syncope, and can show time spent in AF.")
    ]),

    // ------------------------------------------------------------------
    D("dev-icd-candidate", "Patient Needing an ICD", "Patient at risk of sudden cardiac death from VT/VF. Secondary prophylaxis after a VT/VF arrest not due to a completely reversible cause; primary prophylaxis for LVEF ≤ 30% and related criteria.", [
      S("overview", "What an ICD does", "<p>The ICD treats patients at risk of <strong>sudden cardiac death from ventricular tachyarrhythmias</strong>.</p><ul><li>Delivers an <strong>80-joule shock</strong> for monomorphic VT, polymorphic VT, and VF; re-evaluates the rhythm; if VT/VF persists, <strong>reverses polarity</strong> for subsequent shocks.</li><li>May <strong>overdrive pace</strong> the arrhythmia instead of shocking.</li><li>Delivers a programmed <strong>maximum number of shocks</strong> per episode, then stops; the cardiology office is alerted.</li><li>Discrimination algorithms minimize shocks for AF, sinus tach, and other SVTs; modern ICDs <strong>record events</strong> and can do dual-chamber, rate-responsive pacing for bradycardia.</li></ul>"),
      S("indications", "Indications", Tbl(["Type", "Indication"], [
        ["<strong>Secondary prophylaxis</strong>", "<strong>First-line</strong> for survivors of <strong>VT or VF arrest not caused by a completely reversible factor</strong> (controversial when the cause is fixed, e.g., stented MI or a stopped QT-prolonging drug). ICD is superior to antiarrhythmics; data less robust for women and elderly."],
        ["<strong>Primary prophylaxis</strong> (class I)", "<strong>LVEF ≤ 30%</strong>, if due to MI at least <strong>40 days post-MI</strong><br>LVEF ≤ 35% with <strong>NYHA II or III</strong> (≥ 40 days post-MI if MI)<br>LVEF ≤ 40% from prior MI with <strong>inducible VT/VF on EPS</strong><br>Structural heart disease with <strong>sustained VT</strong><br><strong>Syncope of undetermined origin</strong> with inducible VT/VF on EPS"],
        ["Class IIa (notes)", "Unexplained syncope with LV dysfunction/nonischemic CM; sustained VT with normal EF; HCM with ≥ 1 major risk factor; ARVD/C with SCD risk factors; long QT or CPVT with syncope/VT on beta blockers; Brugada with syncope/VT; outpatients awaiting heart transplant; cardiac sarcoid, giant cell myocarditis, Chagas"]
      ]) + HY("Secondary = already survived VT/VF arrest (not completely reversible). Primary = LVEF ≤ 30% (40 days after MI).") + "<p>Class I = useful, benefit greatly outweighs risk, should be given. Class IIa = benefit outweighs risk, reasonable to give.</p>"),
      S("device", "Device types & placement", Tbl(["", "Transvenous ICD (TV-ICD)", "Subcutaneous ICD (S-ICD)"], [
        ["Lead", "Shocking lead to the ventricle via a vein", "Shocking lead <strong>tunneled to the sternum</strong> (FDA approved 2012)"],
        ["Pacing", "Can pace bradyarrhythmias", "<strong>Limited pacing</strong> capability"],
        ["Placement", "Very similar to pacemaker implantation", "—"]
      ]) + "<p>Early ICDs were bulky “shock boxes” placed in the abdomen via thoracotomy with a <strong>2-year</strong> battery; modern ICDs average <strong>~8 years</strong>. If a pacemaker is also needed, combine into one pulse generator.</p>")
    ], [
      Q("indications", "A patient survives an out-of-hospital VF arrest with no completely reversible cause found. What is first-line therapy to prevent sudden death?", ["ICD for secondary prophylaxis", "Amiodarone alone", "Permanent pacemaker", "No therapy if EF is normal"], 0, "ICDs are first-line secondary prophylaxis for survivors of VT/VF arrest not caused by a completely reversible factor, superior to antiarrhythmics."),
      Q("indications", "Which LVEF threshold is the classic primary-prophylaxis ICD indication named in the objectives?", ["LVEF ≤ 30%", "LVEF ≤ 50%", "LVEF ≤ 45%", "LVEF ≤ 15% only"], 0, "An ICD is indicated for an EF of 30% or less (at least 40 days post-MI if due to MI)."),
      Q("indications", "A patient with an anterior MI 2 weeks ago has an LVEF of 25%. When does he meet the MI-related ICD primary-prophylaxis criterion?", ["At least 40 days after the MI", "Immediately, before discharge", "At 7 days post-MI", "Only after 1 year"], 0, "For LVEF ≤ 30% due to MI, the ICD is placed at least 40 days post-MI."),
      Q("indications", "A patient with prior MI has an LVEF of 38% and inducible VT on an electrophysiology study. What is indicated?", ["ICD (primary prophylaxis)", "No device because EF is above 35%", "Permanent pacemaker", "Repeat echo in 5 years"], 0, "LVEF ≤ 40% from prior MI with inducible VT/VF on EPS is a class I primary-prophylaxis indication."),
      Q("indications", "Which situation makes ICD for secondary prophylaxis controversial?", ["VF arrest caused by a QT-prolonging drug that is then discontinued", "VT arrest with no identifiable cause", "VF arrest in a patient with LVEF of 25%", "Recurrent sustained VT with structural heart disease"], 0, "Secondary prophylaxis applies when the cause is not completely reversible; a stented MI or a stopped QT-prolonging drug makes it controversial."),
      Q("indications", "What is the main difference between primary and secondary ICD prophylaxis?", ["Secondary follows a survived VT/VF arrest; primary is for high-risk patients who have not had one", "Primary is for bradycardia; secondary for tachycardia", "Primary uses a subcutaneous device; secondary a transvenous one", "Secondary is only for women and the elderly"], 0, "Secondary = after surviving VT/VF arrest; primary = strong risk factors (e.g., LVEF ≤ 30%) before any event."),
      Q("indications", "Which is a class I primary-prophylaxis ICD indication?", ["LVEF ≤ 35% with NYHA class II or III symptoms", "LVEF 55% with palpitations", "Symptomatic sick sinus syndrome", "First-degree AV block"], 0, "Class I primary indications include LVEF ≤ 35% with NYHA II–III symptoms (≥ 40 days post-MI if MI)."),
      Q("overview", "What energy shock does an ICD deliver for VT or VF?", ["80 joules", "8 joules", "200 joules", "360 joules"], 0, "ICDs deliver an 80-joule shock for monomorphic VT, polymorphic VT, and VF."),
      Q("overview", "If VT persists after an ICD’s first shock, what does the device do?", ["Reverses polarity between electrodes and delivers subsequent shocks", "Turns itself off permanently", "Switches to asynchronous pacing at 40 bpm", "Shocks indefinitely without limit"], 0, "The device re-evaluates; if VT/VF persists it reverses polarity for subsequent shocks, up to a programmed maximum."),
      Q("overview", "Besides shocking, what can an ICD do to terminate a ventricular arrhythmia?", ["Overdrive pace it", "Deliver adenosine", "Ablate the AV node", "Cool the myocardium"], 0, "Sometimes the ICD will attempt to overdrive pace the arrhythmia rather than deliver a shock."),
      Q("device", "What is the average battery life of a modern ICD?", ["About 8 years", "About 2 years", "About 20 years", "About 1 year"], 0, "Modern ICDs average about 8 years; early ICDs lasted about 2 years."),
      Q("device", "Which is a limitation of a subcutaneous ICD (S-ICD)?", ["Limited pacing capability", "It cannot shock VF", "It requires a thoracotomy", "It must be placed in the abdomen"], 0, "S-ICDs have a shocking lead tunneled to the sternum and limited pacing capabilities."),
      Q("device", "A patient needs both an ICD and pacing. How is this handled?", ["Combine them so all functions run off one pulse generator", "Place two separate generators on opposite sides", "Place a pacemaker now and an ICD after 10 years", "Use a transcutaneous pacer at home"], 0, "A pacemaker should be combined with an ICD or CRT device so all devices run off one pulse generator.")
    ]),

    // ------------------------------------------------------------------
    D("dev-icd-shock", "ICD Shock: Appropriate and Inappropriate", "The patient whose ICD fires goes to the ER for admission, interrogation, and correction of reversible causes. Inappropriate shocks usually come from an atrial arrhythmia driving the ventricular rate over the shock limit.", [
      S("management", "When the ICD fires", "<ul><li>Patients are told to <strong>go to the ER</strong> if their ICD fires.</li><li>Generally <strong>admit</strong> to correct any <strong>reversible cause</strong> and see cardiology.</li><li><strong>Order a device interrogation</strong>: modern ICDs record cardiac events.</li><li>The cardiology office is alerted when the device delivers shocks.</li><li>Most cardiologists recommend being <strong>shock-free for 6 months before driving</strong>.</li></ul>" + HY("ICD fired → ER, admit, correct reversible causes, interrogate the device.")),
      S("inappropriate", "Inappropriate shocks", "<p>Shocks <strong>not</strong> triggered by accurate detection of VT or VF. In one major trial <strong>11.5%</strong> of ICD patients got inappropriate shocks and <strong>31.2%</strong> of all shocks were inappropriate.</p><p>Typical cause: an <strong>atrial arrhythmia accelerates the ventricular rate</strong> above the shock threshold. Discrimination algorithms try to avoid shocks for AF, sinus tach, and other SVTs.</p><p>Why it matters: every shock sends the patient to the ER, and <strong>ICD shocks hurt</strong>.</p>")
    ], [
      Q("management", "A patient with an ICD feels a shock while gardening and now feels fine. What is the appropriate advice?", ["Go to the ER for evaluation", "Ignore it if symptoms resolve", "Remove the device magnet at home", "Schedule a routine 6-month visit"], 0, "Patients are instructed to go to the ER if their ICD fires; they are generally admitted."),
      Q("management", "A patient arrives in the ED after an ICD shock. Which test should be ordered to see what happened?", ["Device interrogation", "Cardiac MRI", "Exercise stress test", "Holter monitor placement"], 0, "Modern ICDs record cardiac events; order a device interrogation."),
      Q("management", "Why is a patient generally admitted after an ICD shock?", ["To correct any reversible cause and see cardiology", "To replace the battery immediately", "To explant the leads", "To start lifelong antibiotics"], 0, "Patients are generally admitted to correct any reversible cause and to be seen by cardiology."),
      Q("management", "How long do most cardiologists recommend an ICD patient be shock-free before driving?", ["6 months", "1 week", "1 month", "5 years"], 0, "Most cardiologists recommend that patients with an ICD be shock free for six months before driving."),
      Q("inappropriate", "What is the typical cause of an inappropriate ICD shock?", ["An atrial arrhythmia accelerating the ventricular rate above the shock limit", "Ventricular fibrillation", "Polymorphic VT", "A dead battery"], 0, "Inappropriate shocks usually occur when an atrial arrhythmia speeds the ventricular rate beyond the programmed shock limit."),
      Q("inappropriate", "A patient with an ICD and paroxysmal atrial fibrillation receives a shock during a rapid AF episode; interrogation shows no VT or VF. What is this?", ["An inappropriate shock", "Appropriate secondary prophylaxis", "Oversensing of electrocautery", "Lead infection"], 0, "A shock not precipitated by accurate detection of VT/VF is inappropriate; AF with a fast ventricular response is the typical cause."),
      Q("inappropriate", "In the major trial cited, roughly what fraction of all ICD shocks were inappropriate?", ["About 31%", "About 1%", "About 75%", "About 5%"], 0, "11.5% of ICD patients received inappropriate shocks, and 31.2% of all shocks were deemed inappropriate."),
      Q("inappropriate", "Why are inappropriate ICD shocks a significant problem?", ["They are painful and send the patient to the ER", "They permanently disable the device", "They always cause VF", "They require lead extraction"], 0, "Patients are counseled to go to the ER whenever shocked, and ICD shocks hurt.")
    ]),

    // ------------------------------------------------------------------
    D("dev-precautions", "Device Precautions and EMI", "Everyday safety for a patient with a pacemaker or ICD: wallet card, MRI caution, distances from electromagnetic sources, and safe ACLS and CPR.", [
      S("identification", "Identification & imaging", "<ul><li>Carry a <strong>wallet card</strong> identifying the device.</li><li><strong>Radio-opaque codes</strong> on the pulse generator seen on <strong>CXR</strong> can identify make and model.</li><li>Patients with a pacemaker or ICD <strong>generally cannot have MRIs</strong>; some devices are MRI-safe – <strong>check with cardiology</strong>.</li></ul>"),
      S("emi", "Electromagnetic interference", emiTable),
      S("acls", "ACLS, defibrillation & CPR", "<ul><li><strong>Pacemaker:</strong> ACLS and defibrillation are safe; place paddles/pads <strong>10 cm from the pulse generator</strong>.</li><li><strong>ICD:</strong> during an event the ICD should act to defibrillate. Rescuers can safely do <strong>CPR</strong>; some current may cause mild discomfort, but there has <strong>never been a serious rescuer injury</strong>. If external defibrillation is needed, pads 10 cm from the generator.</li></ul>")
    ], [
      Q("emi", "How far should a patient keep a cell phone or wireless charger from their ICD site?", ["About 6 inches (15 cm)", "About 1 inch", "At least 10 feet", "No precaution is needed"], 0, "Cell phones, mobile devices, magnets, headphones, and wireless chargers should be kept over 6 inches (about 15 cm) from the device when on."),
      Q("emi", "A welder with a new pacemaker asks how close he can stand to welding equipment. What is the counseling?", ["At least 2 feet (0.6 m) away", "At least 6 inches away", "At least 10 cm away", "Welding is no risk"], 0, "Stand at least 2 feet (0.6 meters) from welding equipment, high-voltage transformers, or motor-generator systems."),
      Q("emi", "Which household device poses little or no risk to a pacemaker or ICD?", ["Microwave oven", "Wireless charger held over the device", "Headphones resting on the chest over the device", "A magnet in a shirt pocket"], 0, "Microwaves, TVs, radios, toasters, electric blankets, shavers, drills, computers, and GPS pose little or no risk."),
      Q("emi", "How should airport security screening be handled for a patient with an ICD?", ["Limit a hand-held metal detector to under 30 seconds over the site, or request a manual search", "Avoid all air travel", "Turn the ICD off before flying", "Hold the device magnet over the site"], 0, "ICDs may set off alarms; limit hand-held detectors to under 30 seconds over the site or request a manual search."),
      Q("identification", "An unconscious patient has a device visible on CXR. What can help identify the make and model?", ["Radio-opaque codes on the pulse generator", "Lead length on echo", "The scar location", "A serum troponin"], 0, "Radio-opaque codes on the pulse generator seen on CXR may help identify the make and model; patients should also carry a wallet card."),
      Q("identification", "A patient with a pacemaker needs a brain MRI. What is the correct approach?", ["Check with cardiology; most devices are not MRI-safe but some are", "Proceed with no precautions", "Deactivate the device with a magnet and proceed", "MRI is always absolutely safe with modern devices"], 0, "Patients with PPMs and ICDs generally cannot have MRIs; some devices are safe, so check with cardiology."),
      Q("acls", "A patient with a pacemaker is in VF. Where should the defibrillator pads go?", ["At least 10 cm from the pulse generator", "Directly over the pulse generator", "Defibrillation is contraindicated", "On the back only, never the chest"], 0, "Defibrillation is safe with a PPM; place pads 10 cm away from the pulse generator."),
      Q("acls", "A bystander is hesitant to do CPR on a collapsed person with an ICD. What is accurate?", ["CPR is safe; current may cause mild discomfort but no serious rescuer injury has occurred", "CPR is contraindicated with an ICD", "Rescuers must wait until the ICD battery dies", "Rescuers must wear insulated gloves before touching"], 0, "Rescuers can safely perform CPR; some current may enter the rescuer and cause mild discomfort, but there has never been a serious case of rescuer injury.")
    ]),

    // ------------------------------------------------------------------
    D("dev-perioperative", "Device Patient Going to Surgery", "Electrocautery EMI is oversensed: a pacemaker may stop pacing (asystole in a dependent patient) and an ICD may shock. Plan with cardiology; a magnet makes a PPM pace asynchronously and suspends ICD shocks.", [
      S("risk", "Why surgery is risky", Tbl(["Device", "Effect of EMI from electrocautery", "Consequence"], [
        ["<strong>Pacemaker</strong>", "<strong>Oversensing</strong>: cautery noise read as cardiac activity → device does not fire", "<strong>Profound bradycardia/asystole</strong> in a pacemaker-dependent patient"],
        ["<strong>ICD</strong>", "Cautery noise oversensed as VT/VF", "<strong>Inappropriate shock</strong> → patient movement hazards the patient and staff"]
      ]) + "<p>Electrocautery is the biggest issue, but other devices (e.g., <strong>nerve stimulators</strong>) can also interfere. For planned surgery, especially <strong>above the umbilicus</strong>, <strong>cardiology should assist in pre-op planning</strong>.</p>"),
      S("magnet", "Magnet response", Tbl(["", "Pacemaker", "ICD"], [
        ["Magnet over device", "<strong>Asynchronous pacing</strong> at a fixed rate with a fixed AV delay; paces for the whole case", "<strong>Shock function suspended</strong>"],
        ["Watch for", "Near <strong>end of battery life</strong> the magnet rate may not be adequate", "Apply <strong>pacer/defib pads before prep and drape</strong>; use an external defibrillator/pacer if needed"]
      ]) + HY("Magnet on a pacemaker = pace asynchronously. Magnet on an ICD = no shocks (external pads on).")),
      S("postop", "Post-op & central lines", "<ul><li>Post-op the device is <strong>reprogrammed by cardiology</strong> or the <strong>magnet is removed</strong>; monitor on <strong>telemetry</strong> in PACU or ICU.</li><li>If surgery was <strong>emergent</strong> or the device <strong>delivered shocks or pacing</strong> during the case, cardiology does a closer <strong>interrogation</strong>.</li><li><strong>Central lines:</strong> guidewires can <strong>short out or dislodge</strong> transvenous leads and cause irreversible damage; risk is highest in the <strong>first 3 months</strong> after implant.</li></ul>")
    ], [
      Q("risk", "During surgery, a pacemaker-dependent patient becomes asystolic while the surgeon uses electrocautery. What explains this?", ["Oversensing: the pacemaker reads cautery EMI as cardiac activity and does not fire", "Battery depletion from the cautery", "Lead perforation", "The pacemaker switched to asynchronous mode"], 0, "EMI from cautery is interpreted as native electrical activity (oversensing), so the pacemaker withholds pacing, causing bradycardia/asystole."),
      Q("risk", "Why is an ICD disabled before surgery?", ["Cautery EMI can be oversensed and trigger an inappropriate shock that moves the patient", "To save battery life", "Because ICDs cannot pace", "To prevent device infection"], 0, "Oversensed cautery EMI can make an ICD fire inappropriately; patient movement from a shock endangers the patient and staff."),
      Q("risk", "Which surgical patient with a device most needs cardiology involvement in pre-op planning?", ["A patient with an ICD having surgery above the umbilicus", "A patient with no device having knee surgery", "A patient with a pacemaker having a dental cleaning without cautery", "A patient with a remote history of temporary pacing"], 0, "When surgery is planned, especially above the umbilicus in a patient with a PPM or ICD, cardiology should assist in pre-op planning."),
      Q("magnet", "What happens when a magnet is placed over most permanent pacemakers?", ["Asynchronous pacing at a fixed rate with a fixed AV delay", "Pacing stops completely", "The device delivers a shock", "Rate-responsive pacing is enabled"], 0, "A magnet initiates asynchronous pacing at a fixed rate with a fixed AV delay for the whole procedure."),
      Q("magnet", "What happens when a magnet is placed over an ICD during surgery?", ["Its shock (tachyarrhythmia) function is suspended", "It begins asynchronous pacing", "It delivers a test shock", "It permanently resets"], 0, "ICD function is suspended during surgery by placing a magnet over the device."),
      Q("magnet", "Before prepping and draping a patient whose ICD has been suspended with a magnet, what must the team do?", ["Apply external pacer/defibrillator pads to the chest", "Start prophylactic amiodarone", "Remove the device leads", "Place a transvenous pacer"], 0, "Pacer/defib pads go on before prep and drape; an external device delivers any needed shock or pacing."),
      Q("magnet", "When might magnet-induced pacing be inadequate during surgery?", ["When the pacemaker is near the end of battery life", "When the patient is young", "When the case is below the umbilicus", "When the patient has a dual-chamber device"], 0, "If the pacemaker is at the end of battery life, the magnet rate may not be adequate."),
      Q("postop", "After surgery in which the ICD delivered a shock, what is needed?", ["A closer interrogation by cardiology", "Immediate generator change", "No follow-up if the patient is stable", "Device explant"], 0, "If surgery was emergent or the device delivered shocks or pacing, cardiology needs to do a closer interrogation."),
      Q("postop", "How is a device patient managed immediately after surgery?", ["Device reprogrammed or magnet removed, then telemetry in PACU or ICU", "Discharged directly from the OR", "Magnet left in place for 1 week", "MRI to confirm lead position"], 0, "Post-op, cardiology reprograms the device or the magnet is removed, and the patient is monitored on telemetry."),
      Q("postop", "A patient had a dual-chamber pacemaker placed 6 weeks ago and now needs a central line. What is the main concern?", ["The guidewire can dislodge or short out the leads; risk is highest in the first 3 months", "The line will drain the battery", "The line will trigger the magnet response", "There is no concern with central lines"], 0, "Central line guidewires can short out or dislodge transvenous leads; risk is highest in the first 3 months after insertion.")
    ]),

    // ------------------------------------------------------------------
    D("dev-lead-complications", "Lead Complications", "Transvenous leads carry small risks: insertion trauma (perforation, tamponade), infection, subclavian vein thrombosis/occlusion, tricuspid regurgitation, and lead fracture causing device malfunction.", [
      S("complications", "Transvenous lead complications", Tbl(["Complication", "What happens"], [
        ["<strong>Insertion trauma</strong>", "Injury to cardiac structures at implant: <strong>perforation, tamponade</strong>"],
        ["<strong>Infection</strong>", "<strong>Bacteremia can seed a small clot</strong> on the leads"],
        ["<strong>Venous thrombosis</strong>", "Resultant <strong>subclavian vein occlusion</strong>"],
        ["<strong>Tricuspid valve injury</strong>", "Lead across the valve → <strong>tricuspid regurgitation</strong>"],
        ["<strong>Lead fracture</strong>", "Lead breaks → <strong>device malfunction</strong> → <strong>lead must be replaced</strong>"],
        ["<strong>Dislodgement</strong>", "Central line guidewires can short out or dislodge leads; highest risk in first 3 months"]
      ])),
      S("management", "Management", "<ul><li><strong>Fractured lead</strong> → replace the lead (a battery problem only needs a generator change, which leaves the leads).</li><li>A prior <strong>venous stenosis</strong> is a reason to use <strong>epicardial</strong> leads instead of transvenous ones.</li></ul>")
    ], [
      Q("complications", "A patient develops hypotension, JVD, and muffled heart sounds shortly after pacemaker lead placement. What complication is most likely?", ["Cardiac perforation with tamponade", "Lead fracture", "Pocket erosion", "Battery depletion"], 0, "Trauma to cardiac structures at insertion can cause perforation and tamponade."),
      Q("complications", "A patient with a transvenous pacemaker develops a new holosystolic murmur at the LLSB. What lead complication explains it?", ["Tricuspid valve injury causing tricuspid regurgitation", "Mitral valve prolapse", "Aortic stenosis", "Subclavian steal"], 0, "Transvenous leads can injure the tricuspid valve, resulting in tricuspid regurgitation."),
      Q("complications", "A patient with a pacemaker develops arm swelling on the device side. Which lead complication is suspected?", ["Venous thrombosis with subclavian vein occlusion", "Lead fracture", "Inappropriate shock", "Tricuspid regurgitation"], 0, "Transvenous leads are associated with venous thrombosis and resultant subclavian vein occlusion."),
      Q("complications", "How can bacteremia lead to device infection through the leads?", ["It can seed a small clot on the leads", "It drains the battery", "It causes the leads to fracture", "It triggers the magnet response"], 0, "Bacteremia can seed a small clot on the leads, causing lead infection."),
      Q("management", "Interrogation shows device malfunction from a fractured lead. What is the treatment?", ["Replace the lead", "Generator change only", "Place a magnet over the device", "Observation"], 0, "If a lead breaks or fractures, causing malfunction, the lead must be replaced."),
      Q("management", "Which situation calls for epicardial rather than transvenous leads?", ["Venous stenosis", "A first-time dual-chamber pacemaker", "Age over 70", "Need for rate-response pacing"], 0, "Epicardial leads are used when there is an anatomic reason to avoid transvenous placement, such as venous stenosis.")
    ]),

    // ------------------------------------------------------------------
    D("dev-device-infection", "Cardiac Device Infection", "Infection of the pocket or leads. Risk is higher with a generator change and with a pocket hematoma. Lead infection causes persistent bacteremia with a vegetation on TEE. Any infected device and its leads must be explanted.", [
      S("causes", "How devices get infected", Tbl(["Route", "Clue"], [
        ["<strong>Pocket infection at insertion</strong>", "Infected pocket incision"],
        ["<strong>Pocket erosion</strong>", "Pocket erodes due to <strong>weight loss</strong>"],
        ["<strong>Hematogenous seeding</strong>", "Bacteremia seeds the device, usually the <strong>leads</strong> → <strong>persistent bacteremia</strong>"]
      ])),
      S("risk", "Risk factors", "<ul><li>A <strong>generator change</strong> is more likely to cause infection than a <strong>de novo implant</strong>.</li><li>A <strong>pocket hematoma</strong> raises infection risk from <strong>0.98% to 22.7%</strong>.</li></ul>" + HY("Pocket hematoma: infection risk 0.98% → 22.7%. Generator change &gt; new implant.")),
      S("workup", "Workup", "<ul><li>Suspect lead infection with <strong>persistent bacteremia</strong>. <em>Clarification (standard reference): persistent bacteremia is shown with repeat blood cultures.</em></li><li><strong>TEE</strong> may show a <strong>vegetation on the lead</strong>.</li><li>Examine the pocket for infection or erosion.</li></ul>"),
      S("management", "Management", "<ul><li>Anytime a pacemaker or ICD is infected, <strong>the device and the leads must be explanted</strong>.</li><li>A <strong>period of antibiotic therapy</strong> is required before a <strong>new device</strong> is implanted.</li></ul>" + HY("Infected device → remove generator AND leads → antibiotics → then reimplant."))
    ], [
      Q("risk", "Which procedure carries a higher risk of device infection?", ["Generator change", "De novo implant", "Device interrogation", "Magnet application"], 0, "A generator change is more likely to cause a device infection than a de novo implant."),
      Q("risk", "A pocket hematoma increases device infection risk from about 1% to about what?", ["About 23%", "About 2%", "About 5%", "About 75%"], 0, "A pocket hematoma increases infection risk from 0.98% to 22.7%."),
      Q("causes", "A thin elderly patient with a pacemaker has lost significant weight and the generator is now visible through the skin. What is the concern?", ["Pocket erosion leading to device infection", "Lead fracture", "Subclavian vein thrombosis", "Inappropriate shock"], 0, "A pocket can erode due to weight loss, a route to device infection."),
      Q("workup", "A patient with an ICD has Staph aureus bacteremia that persists despite antibiotics. What study can show a lead vegetation?", ["Transesophageal echocardiogram (TEE)", "Chest x-ray", "Device interrogation", "Resting EKG"], 0, "Lead infection causes persistent bacteremia, and a vegetation may be seen on the lead during a TEE."),
      Q("workup", "What finding is the hallmark of a device seeded from bacteremia?", ["Persistent bacteremia", "A single negative blood culture", "Low battery voltage", "Prolonged QT"], 0, "Hematogenous seeding usually affects the leads and causes a persistent bacteremia."),
      Q("management", "A pacemaker pocket is infected. What is the definitive management?", ["Explant the device and all leads", "Oral antibiotics and keep the device", "Generator change only", "Incision and drainage only"], 0, "Anytime a pacemaker or ICD becomes infected, the device and the leads must be explanted."),
      Q("management", "After an infected ICD and its leads are removed, when is a new device implanted?", ["After a period of antibiotic therapy", "Immediately in the same procedure", "Never; ICDs cannot be reimplanted", "Only after 10 years"], 0, "Patients require a period of antibiotic therapy before a new device can be implanted."),
      Q("management", "A patient with a lead vegetation on TEE asks if antibiotics alone can clear the infection while keeping the leads. What is correct?", ["No; the device and leads must be removed", "Yes, if the bacteremia clears in 48 hours", "Yes, if only the leads are infected", "Yes, with lifelong suppressive antibiotics"], 0, "Any infected pacemaker or ICD requires explantation of the device and leads.")
    ])
  ]);
}());
